WITH Base AS (SELECT * FROM suppliers WHERE country NOT IN ('US', 'SG', 'DE') OR LOWER(supplier_name) LIKE '%aci%'), Agg AS (SELECT CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, country, MAX(rating) AS max_rating, COUNT(CASE WHEN city = 'Singapore' THEN 1 END) AS singapore_count FROM Base GROUP BY CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END, country) SELECT rating_bucket, country, max_rating, singapore_count FROM Agg;
